package com.example.examplemod.client.map;

/** Native 16x16 toolbar pictograms, independent of font glyph coverage and GUI language. */
public enum ToolbarGlyph {
    BACK("................", "................", "................", ".......##.......", "......###.......", ".....###........", "....###.........", "...##########...", "...##########...", "....###.........", ".....###........", "......###.......", ".......##.......", "................", "................", "................"),
    FORWARD("................", "................", "................", ".......##.......", ".......###......", "........###.....", ".........###....", "...##########...", "...##########...", ".........###....", "........###.....", ".......###......", ".......##.......", "................", "................", "................"),
    CENTER("................", "................", "..####....####..", "..####....####..", "..##........##..", "..##...##...##..", ".......##.......", ".....######.....", ".....######.....", ".......##.......", "..##...##...##..", "..##........##..", "..####....####..", "..####....####..", "................", "................"),
    SEARCH("................", ".....###........", "...#######......", "..##.....##.....", "..#.......#.....", ".##.......##....", ".##.......##....", ".##.......##....", "..#.......#.....", "..##.....##.....", "...#########....", ".....###..###...", "...........###..", "............###.", ".............##.", "................"),
    LAYERS("................", "......####......", "....##....##....", "..##........##..", "................", "..##........##..", "....##....##....", "......####......", "..##........##..", "....##....##....", "......####......", "..##........##..", "....##....##....", "......####......", "................", "................"),
    ALERT("................", "................", ".......##.......", ".......##.......", "......####......", "......####......", ".....######.....", ".....######.....", "....##.##.##....", "....##....##....", "...##..##..##...", "...##......##...", "..############..", "..############..", "................", "................"),
    GUIDE("................", "................", "...####..####...", ".##############.", ".##....##....##.", ".##....##....##.", ".##.##.##.##.##.", ".##....##....##.", ".##....##....##.", ".##.##.##.##.##.", ".##....##....##.", ".##....##....##.", ".##############.", "...##########...", "................", "................"),
    CLOSE("................", "................", "................", "...##......##...", "....##....##....", ".....##..##.....", "......####......", ".......##.......", "......####......", ".....##..##.....", "....##....##....", "...##......##...", "..##........##..", "................", "................", "................");
    public static final int SIZE = 16;
    private final int[] rows = new int[SIZE];
    ToolbarGlyph(String... pixels) {
        if (pixels.length != SIZE) throw new IllegalArgumentException("glyph height");
        for (int y = 0; y < SIZE; y++) {
            if (pixels[y].length() != SIZE) throw new IllegalArgumentException("glyph width");
            for (int x = 0; x < SIZE; x++) if (pixels[y].charAt(x) == '#') rows[y] |= 1 << x;
        }
    }
    public boolean pixel(int x, int y) {
        return x >= 0 && x < SIZE && y >= 0 && y < SIZE && (rows[y] & (1 << x)) != 0;
    }
}
